import crypto from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = path.join(root, "CAPSTONE/source/bus311-capstone.json");
const sourceBytes = await fs.readFile(sourcePath);
const capstone = JSON.parse(sourceBytes.toString("utf8"));
const sourceHash = crypto.createHash("sha256").update(sourceBytes).digest("hex");
const outputDir = path.join(root, "CAPSTONE");

const esc = (value) => String(value ?? "")
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

const materialById = new Map(capstone.materials.map((item) => [item.materialId, item]));
const fileName = (item) => path.basename(item.path);
const publicHref = (item) => `./${fileName(item)}`;
const canvasHref = (item) => `${capstone.hub.publicUrl}${encodeURIComponent(fileName(item))}`;
const presentationDates = capstone.presentationSchedule.dates.map((date) => {
  const parsed = new Date(`${date}T12:00:00-05:00`);
  return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(parsed);
}).join(", ");
const milestoneDueById = new Map(capstone.milestones.map((item) => [item.milestoneId, item.due]));
const stageById = new Map(capstone.hub.stages.map((stage) => [stage.stageId, stage]));
const stageOne = capstone.hub.stages.find((stage) => stage.stageId === "S01_SCOPE");

const resourceGroups = [
  { stageId: "OVERVIEW", title: "Assignment and scoring", eyebrow: "Project overview", ids: ["ASSIGNMENT", "ASSIGNMENT_DOCX", "STUDENT_RUBRIC"] },
  { stageId: "S01_SCOPE", label: "Stage 1", title: "Explore the company and a CFO decision", eyebrow: `Due ${stageById.get("S01_SCOPE").dateLabel}`, due: milestoneDueById.get("M01"), ids: ["M01_MENU", "M01_EXPLORATION"] },
  { stageId: "S02_REVENUE", label: "Stage 2", title: "Build the revenue case", eyebrow: `Due ${stageById.get("S02_REVENUE").dateLabel}`, due: milestoneDueById.get("M02"), ids: ["REVENUE_GUIDE", "REVENUE_WORKBOOK", "HYPOTHESIS_CHECKLIST", "M02_RUBRIC"] },
  { stageId: "S03_VALUE", label: "Stage 3", title: "Model value and scenarios", eyebrow: `Due ${stageById.get("S03_VALUE").dateLabel}`, due: milestoneDueById.get("M03"), ids: ["VALUATION_MODEL"] },
  { stageId: "S04_RED_TEAM", label: "Stage 4", title: "Challenge and revise", eyebrow: `Due ${stageById.get("S04_RED_TEAM").dateLabel}`, due: milestoneDueById.get("M04"), ids: ["AI_GUIDE", "CAPAJ", "RED_TEAM"] },
  { stageId: "S05_BOARD", label: "Stage 5", title: "Brief the Board", eyebrow: "Final files due November 30 at 12:30 p.m. ET", due: capstone.finalSubmission.deadline, ids: ["BOARD_TEMPLATE", "SUMMARY_TEMPLATE", "SUMMARY_GUIDE", "SUMMARY_EXAMPLE"] },
];
const stageResourceGroups = resourceGroups.filter((group) => group.stageId !== "OVERVIEW");

function publicResourceGroup(group, className = "resource-group") {
  return `<section class="${className}"><p class="kicker">${esc(group.eyebrow)}</p><h3>${esc(group.title)}</h3><div class="resource-grid">${group.ids.map((id) => {
    const item = materialById.get(id);
    const extension = path.extname(item.path).slice(1).toUpperCase();
    return `<a class="resource-card" href="${esc(publicHref(item))}"><span>${esc(extension)}</span><strong>${esc(item.label)}</strong><small>Open or download this student file</small></a>`;
  }).join("")}</div></section>`;
}

function publicResourceGroups() {
  return resourceGroups.map((group) => publicResourceGroup(group)).join("");
}

function publicCurrentStageResources() {
  return `<div class="current-stage-files" data-current-stage-files>${stageResourceGroups.map((group, index) => `<div class="current-file-set" data-current-file-set data-stage-label="${esc(group.label)}" data-stage-due="${esc(group.due)}"${index === 0 ? "" : " hidden"}>${publicResourceGroup(group, "resource-group current-resource-group")}</div>`).join("")}</div>`;
}

function publicStageCards() {
  return capstone.hub.stages.map((stage) => {
    const guide = materialById.get(stage.guideMaterialId);
    return `<article class="stage-card"><p class="stage-label">${esc(stage.label)}</p><h3>${esc(stage.title)}</h3><dl><div><dt>Outcome</dt><dd>${esc(stage.outcome)}</dd></div><div><dt>Due</dt><dd>${esc(stage.dateLabel)}</dd></div><div><dt>Submit</dt><dd>${esc(stage.requiredSubmission)}</dd></div></dl><details><summary>Stage details</summary><p>${esc(stage.summary)}</p>${guide ? `<a href="${esc(publicHref(guide))}">Open ${esc(guide.label)}</a>` : ""}</details></article>`;
  }).join("");
}

function publicDecisionMenu() {
  const families = capstone.hub.decisionFamilies.map((item) => `<article><h3>${esc(item.family)}</h3><p>${esc(item.summary)}</p><small>Includes: ${item.includes.map(esc).join(" · ")}</small></article>`).join("");
  const allOptions = capstone.hub.decisionMenu.map((item) => `<article><h3>${esc(item.area)}</h3><p>${esc(item.prompt)}</p></article>`).join("");
  return `${families}<details class="all-decisions"><summary>See all 10 decision options</summary><div class="decision-grid all-option-grid">${allOptions}</div></details>`;
}

function publicFaqs() {
  return capstone.hub.faqs.map((item) => `<details><summary>${esc(item.question)}</summary><p>${esc(item.answer)}</p></details>`).join("");
}

function publicChecklist() {
  return capstone.hub.progressChecklist.map((item) => `<li>${esc(item)}</li>`).join("");
}

const stageOneMenu = materialById.get("M01_MENU");
const stageOneExploration = materialById.get("M01_EXPLORATION");
const assignment = materialById.get("ASSIGNMENT");
const studentRubric = materialById.get("STUDENT_RUBRIC");
const aiGuide = materialById.get("AI_GUIDE");
const capajGuide = materialById.get("CAPAJ");
const redTeamRecord = materialById.get("RED_TEAM");
const completeResourceLibrary = publicResourceGroups();

const legacyBoardQuestion = `<aside class="central-question"><h2>Your Board question</h2><p>${esc(capstone.hub.centralQuestion)}</p></aside>`;
const heroStartPanel = `<aside class="hero-start" id="start" aria-labelledby="start-title"><p class="kicker">Start Stage 1</p><h2 id="start-title">${esc(stageOne.title)}</h2><dl><div><dt>What am I doing?</dt><dd>${esc(stageOne.objective)}</dd></div><div><dt>What is due next?</dt><dd><strong>${esc(stageOne.requiredSubmission)}</strong> · Due ${esc(stageOne.dateLabel)}</dd></div></dl><p class="hero-open-label">What do I open now?</p><div class="start-actions"><a class="button" href="${esc(publicHref(stageOneMenu))}">1. Browse potential CFO decisions</a><a class="button secondary" href="${esc(publicHref(stageOneExploration))}">2. Complete the Stage 1 exploration brief</a></div><p class="start-secondary">Details: <a href="${esc(publicHref(assignment))}">assignment</a> · <a href="${esc(publicHref(studentRubric))}">rubric</a></p></aside>`;
const boardQuestionPanel = `<aside class="board-question"><p class="kicker">Your Board question</p><p>${esc(capstone.hub.centralQuestion)}</p></aside>`;

const aiStageSection = `<section class="ai-stage" aria-labelledby="ai-stage-title"><div><p class="kicker">After Stage 1</p><h3 id="ai-stage-title">Use AI to challenge—not replace—your judgment</h3><p>The four C-A-P-A-J checkpoints begin after the exploratory Stage 1 brief. Complete them through the bounded AI guide, then submit the red-team record.</p></div><ol class="ai-checklist">${capstone.hub.aiStageChecklist.map((item) => `<li>${esc(item)}</li>`).join("")}</ol><div class="ai-actions"><a href="${esc(publicHref(aiGuide))}">Open bounded AI guide</a><a href="${esc(publicHref(capajGuide))}">Open C-A-P-A-J prompts</a><a href="${esc(publicHref(redTeamRecord))}">Open red-team record</a></div><div class="guardrail"><strong>AI is not a source.</strong> Stage 1 ideas are exploratory; later checkpoints require independent verification. Never upload raw licensed, private, or instructor-only material.</div></section>`;

const resourceLibrary = `<div class="current-files-intro"><p class="kicker">Current stage files</p><h3 data-current-files-label>Stage 1 files</h3><p>Start with only the files needed for the next milestone. The full ${capstone.materials.length}-file package remains available below.</p></div>${publicCurrentStageResources()}<details class="file-library"><summary>Open the complete file library (${capstone.materials.length} files)</summary><div>${completeResourceLibrary}</div></details>`;

