const currentFilesScript = `<script>(()=>{const sets=[...document.querySelectorAll('[data-current-file-set]')];if(!sets.length)return;const now=Date.now();const current=sets.find((set)=>Date.parse(set.dataset.stageDue)>=now)||sets[sets.length-1];sets.forEach((set)=>{set.hidden=set!==current});const label=document.querySelector('[data-current-files-label]');if(label)label.textContent=current.dataset.stageLabel+' files';})();</script>`;

